#define PHI 1.61803398875  // The golden ratio
#define GOLDEN_ANGLE 2.399963229728653 // The golden angle in radians (~137.5 degrees)
// 2D rotation function
mat2 rot2D(float a) {
    return mat2(cos(a), -sin(a), sin(a), cos(a));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = ( 2.*fragCoord - iResolution.xy ) / iResolution.y;
    vec2 uv2 = fragCoord.xy / iResolution.xy;

    vec3 tex = texture(iChannel0, uv2).rgb;
    uv*= rot2D(iTime*.75);
    //  polar coords
    float angle = atan(uv.y, uv.x);

    float radius = length(uv);
     // Spiral equation
    float goldenSpiral = radius - pow(PHI, angle / GOLDEN_ANGLE); 
    // Repeat the spiral infinitely 
    float th = (.02*iResolution.x)/iResolution.y;
    goldenSpiral = mod(goldenSpiral, th);

    // Smooth gradient for spiral visualization
    float spiralPattern = smoothstep(0.01, 0.02, abs(goldenSpiral)*tex.r);

    // Use the spiral to color the screen
    vec3 color = vec3(spiralPattern) * vec3(1.0, 0.8, 0.2);

    fragColor = vec4(color, 1.0);
}
